<?php
/* TEMPORARY (owner, 11 Nov 2026): full backup, then save the researched Art Events (as unpublished team drafts,
   Admin → Waiting for approval) and Art Institutes (hidden, Admin → Institutes). Nothing is published or shown.
   Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('8d5f215eb436caac5a3dcdaf28cbceccfc3f12824e7bf34d37dffb2325c43216', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/article_lib.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
$D = json_decode(base64_decode(''), true);
$show = function () use ($db) {
    echo "\n== event articles\n"; foreach ($db->query("SELECT id, slug, status, event_start_date, event_end_date FROM articles WHERE type = 'event' ORDER BY id") as $r) echo implode(' | ', array_map('strval', $r)), "\n";
    echo "\n== institutes\n"; foreach ($db->query('SELECT id, name_en, city_en, is_active FROM institutes ORDER BY id') as $r) echo implode(' | ', array_map('strval', $r)), "\n";
};
if (($_GET['a'] ?? '') !== 'run') { echo "ready, database $dbName, ", count($D['events']), " events, ", count($D['institutes']), " institutes\n"; $show(); exit; }
if (is_file(__DIR__ . '/.logs/zz-research-done')) { echo "already run\n"; $show(); exit; }

/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

$ins = $db->prepare("INSERT INTO articles (type, slug, title_en, title_ar, body_en, body_ar, cover_image_path, author_user_id, status, published_at, event_start_date, event_end_date, event_location_en, event_location_ar)
                     VALUES ('event', :slug, :ten, :tar, :ben, :bar, '', NULL, 'draft', NULL, :sd, :ed, :len, :lar)");
foreach ($D['events'] as $e) {
    $ins->execute([':slug' => owUniqueSlug((string) $e['title_en']), ':ten' => $e['title_en'], ':tar' => $e['title_ar'], ':ben' => $e['body_en'], ':bar' => $e['body_ar'],
                   ':sd' => $e['start_date'] ?: null, ':ed' => $e['end_date'] ?: null, ':len' => $e['location_en'], ':lar' => $e['location_ar']]);
    echo "event draft: ", $e['title_en'], "\n";
}
$ii = $db->prepare("INSERT INTO institutes (user_id, name_en, name_ar, city_en, city_ar, description_en, description_ar, logo_path, contact_email, contact_phone, website_url, is_active)
                    VALUES (NULL, :ne, :na, :ce, :ca, :de, :da, '', :em, :ph, :web, 0)");
foreach ($D['institutes'] as $i) {
    $ii->execute([':ne' => $i['name_en'], ':na' => $i['name_ar'], ':ce' => $i['city_en'], ':ca' => $i['city_ar'], ':de' => $i['description_en'], ':da' => $i['description_ar'],
                  ':em' => (string) $i['contact_email'], ':ph' => (string) $i['contact_phone'], ':web' => $i['website_url']]);
    echo "institute (hidden): ", $i['name_en'], "\n";
}
@file_put_contents(__DIR__ . '/.logs/zz-research-done', gmdate('c'));
if (function_exists('owSchemaForget')) owSchemaForget();
$show();
